"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["31253"],{653276(e){e.exports=JSON.parse('{"tag":{"label":"asmt_metric_category","permalink":"/sdk/4.13.0/tags/asmt-metric-category","allTagsPath":"/sdk/4.13.0/tags","count":4,"items":[{"id":"api/assessment/assessment-api","title":"Assessment","description":"Creates a ServiceNow assessment/survey definition (asmtmetrictype) together with its categories (asmtmetriccategory) and questions/metrics (asmtmetric) as a single nested entity. The plugin wires the metrictype and category foreign keys automatically from the nesting structure, so you never set them by hand.","permalink":"/sdk/4.13.0/api/assessment/assessment-api"},{"id":"guides/assessment-guide","title":"Assessment & Survey Guide","description":"Guide for creating ServiceNow Assessments and Surveys (asmtmetrictype) using the Fluent API. Surveys collect user feedback through simple, unscored questionnaires; assessments evaluate, score, and rank assessable records with weighted and normalized results. Both share the same nested structure: type \u2192 categories \u2192 metrics \u2192 definitions. This framework only defines the survey/assessment and its in-platform delivery (a generated instance in the recipient\'s assessment queue) \u2014 it does not email a survey link or send a notification, so to send, email, or notify a recipient you must pair it with an Email Notification.","permalink":"/sdk/4.13.0/guides/assessment-guide"},{"id":"guides/risk-assessment-guide","title":"Change Risk Assessment Guide","description":"Guide for creating ServiceNow Change Risk Assessments (changeriskasmt) using the Fluent API. A risk assessment evaluates change requests to determine a risk level (high, moderate, or low) based on scored questions and configurable thresholds.","permalink":"/sdk/4.13.0/guides/risk-assessment-guide"},{"id":"api/assessment/riskassessment-api","title":"RiskAssessment","description":"Creates a ServiceNow change risk assessment definition (changeriskasmt) together with its risk thresholds (changeriskasmtthreshold), categories (asmtmetriccategory), and questions/metrics (asmtmetric) as a single nested entity. The plugin wires the metric_type, category, and assessment foreign keys automatically from the nesting structure.","permalink":"/sdk/4.13.0/api/assessment/riskassessment-api"}],"unlisted":false}}')}}]);